   "slug": "ctn-arts-1-11-competencia-tributaria",
   "titulo": "CTN arts. 1º-11 — Sistema tributário nacional e competência tributária (texto literal)",
   "tipoDocumento": "LEGISLACAO",
   "area": "tributario",
