   "slug": "doutrina-guerra-fiscal-conflito-icms-iss",
   "titulo": "Doutrina — Guerra fiscal, conflito ICMS × ISS e limites dos convênios",
   "tipoDocumento": "DOUTRINA",
   "area": "tributario",
